IMG_B64 = {"mme_91":"","mme_986":"","ocrbench_382":"","ocrbench_589":"","textvqa_722":"","textvqa_1026":"","textvqa_327":""}


_IMG_CACHE = {}


def image_of(tag):
    if tag not in _IMG_CACHE:
        _IMG_CACHE[tag] = np.array(
            Image.open(io.BytesIO(base64.b64decode(IMG_B64[tag]))).convert("RGB"))
    return _IMG_CACHE[tag]


def panel_pdf(tag, method, pdf):
    d = DATA[tag]
    gh, gw = d["grid"]
    px = d["patch_px"]
    rw, rh = d["resized_wh"]
    sel = np.array(d["methods"][method]["selected"], float)
    idx, scores = sel[:, 0].astype(int), sel[:, 1]
    ranks = np.argsort(np.argsort(scores))
    tvals = ranks / max(len(scores) - 1, 1)
    fig, ax = plt.subplots(figsize=(rw / 100, rh / 100), dpi=100)
    ax.imshow(image_of(tag))
    for t, tv in zip(idx, tvals):
        r, c = divmod(int(t), gw)
        ax.add_patch(Rectangle((c * px, r * px), px, px, facecolor=CMAP(tv),
                               edgecolor=EDGE, linewidth=LW, alpha=ALPHA, zorder=3))
    ax.set_xlim(0, rw)
    ax.set_ylim(rh, 0)
    ax.axis("off")
    fig.subplots_adjust(left=0, right=1, top=1, bottom=0)   # image edge to edge
    pdf.savefig(fig)
    plt.close(fig)


def main(outdir):
    os.makedirs(outdir, exist_ok=True)
    tags = sorted(DATA)
    for t in tags:
        for m in METHODS:
            out = os.path.join(outdir, f"case_{t}_{m}.pdf")
            with PdfPages(out) as pdf:
                panel_pdf(t, m, pdf)
            print("wrote", out)
    for m in METHODS:
        out = os.path.join(outdir, f"all_{m}.pdf")
        with PdfPages(out) as pdf:
            for t in tags:
                panel_pdf(t, m, pdf)
        print("wrote", out, f"({len(tags)} pages)")


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "case7_pdfs")
